// Independent audit: incoming equitable refinement, unrestricted within-cell
// permutation canonicalization, and adjacency-backtracking full automorphisms.
// No canonicalization above order ten; child groups use isomorphism to self.
#include <algorithm>
#include <array>
#include <cstdint>
#include <fstream>
#include <functional>
#include <iostream>
#include <map>
#include <numeric>
#include <set>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>
using namespace std; using G=vector<unsigned>; using P=vector<unsigned>;
uint64_t checks=0,can_calls=0,can_leaves=0,iso_nodes=0;
void req(bool b,string s){++checks;if(!b)throw runtime_error(s);}
unsigned pc(unsigned x){return __builtin_popcount(x);} uint64_t fac(int n){uint64_t x=1;while(n)x*=n--;return x;}
void valid(const G&r){unsigned n=r.size();for(unsigned i=0;i<n;i++){req(r[i]<(1u<<n)&&!(r[i]>>i&1),"valid row range and diagonal");for(unsigned j=0;j<i;j++)req(((r[i]>>j&1)+(r[j]>>i&1))==1,"valid tournament");}}
vector<vector<unsigned>> partition(const G&r){unsigned n=r.size();vector<vector<unsigned>>cells(1);for(unsigned v=0;v<n;v++)cells[0].push_back(v);for(;;){vector<vector<unsigned>>next;for(auto C:cells){map<vector<unsigned>,vector<unsigned>>buckets;for(auto v:C){vector<unsigned>sig;for(auto B:cells){unsigned z=0;for(auto u:B)z+=(r[u]>>v)&1;sig.push_back(z);}buckets[sig].push_back(v);}for(auto x:buckets)next.push_back(x.second);}if(next.size()==cells.size())return next;cells=next;}}
uint64_t canonical(const G&r){req(r.size()<=10,"no target eleven canonicalization");++can_calls;auto cells=partition(r);vector<unsigned>order;uint64_t best=~uint64_t(0);function<void(unsigned)>go=[&](unsigned c){if(c==cells.size()){++can_leaves;uint64_t code=0;unsigned shift=0;for(unsigned j=1;j<r.size();j++)for(unsigned i=0;i<j;i++)code|=uint64_t((r[order[i]]>>order[j])&1)<<shift++;best=min(best,code);return;}auto v=cells[c];sort(v.begin(),v.end());do{order.insert(order.end(),v.begin(),v.end());go(c+1);order.resize(order.size()-v.size());}while(next_permutation(v.begin(),v.end()));};go(0);return best;}
set<P> autos(const G&r){unsigned n=r.size(),all=(1u<<n)-1;auto cells=partition(r);vector<unsigned>col(n);for(unsigned k=0;k<cells.size();k++)for(auto v:cells[k])col[v]=k;vector<int>f(n,-1);set<P>out;function<void(unsigned)>go=[&](unsigned used){++iso_nodes;if(used==all){P p(n);for(unsigned i=0;i<n;i++)p[i]=f[i];out.insert(p);return;}int sel=-1;vector<unsigned>opts;for(unsigned u=0;u<n;u++)if(f[u]<0){vector<unsigned>cand;for(unsigned v=0;v<n;v++)if(!(used>>v&1)&&col[u]==col[v]){bool good=true;for(unsigned a=0;a<n&&good;a++)if(f[a]>=0){good=((r[u]>>a&1)==(r[v]>>f[a]&1));good=good&&(pc(r[u]&r[a])==pc(r[v]&r[f[a]]));}if(good)cand.push_back(v);}if(cand.empty())return;if(sel<0||cand.size()<opts.size()){sel=u;opts=cand;}}for(auto v:opts){f[sel]=v;go(used|(1u<<v));f[sel]=-1;}};go(0);return out;}
struct Obj{G r;set<P>g;};vector<Obj>read_atlas(string file,unsigned n){ifstream in(file);req(bool(in),"atlas open");unsigned N;in>>N;req(bool(in)&&N&&N<1000000,"atlas count guard");vector<Obj>a(N);for(auto &o:a){o.r.resize(n);for(auto &v:o.r)in>>v;unsigned ng;in>>ng;req(bool(in)&&ng&&ng<=fac(n),"action count guard");for(unsigned k=0;k<ng;k++){P p(n);for(auto &v:p)in>>v;req(bool(in),"complete atlas record");auto q=p;sort(q.begin(),q.end());for(unsigned j=0;j<n;j++)req(q[j]==j,"action is permutation");for(unsigned i=0;i<n;i++)for(unsigned j=0;j<n;j++)req((o.r[i]>>j&1)==(o.r[p[i]]>>p[j]&1),"action preserves arcs");req(o.g.insert(p).second,"distinct actions");}valid(o.r);}string s;in>>s;req(s.empty(),"no trailing atlas payload");return a;}
G extend(const G&r,unsigned mask){unsigned n=r.size();G x=r;for(unsigned i=0;i<n;i++)if(mask>>i&1)x[i]|=1u<<n;x.push_back(((1u<<n)-1)^mask);return x;}
G del(const G&r,unsigned root){G x;for(unsigned i=0;i<r.size();i++)if(i!=root){unsigned row=0,jj=0;for(unsigned j=0;j<r.size();j++)if(j!=root){row|=((r[i]>>j)&1)<<jj++;}x.push_back(row);}return x;}
bool ar(const G&r){unsigned n=r.size(),lo=0,hi=0;for(auto row:r){lo+=pc(row)==n/2-1;hi+=pc(row)==n/2;}return lo==n/2&&hi==n/2;}
vector<string>split(string s,char c){stringstream in(s);vector<string>v;while(getline(in,s,c))v.push_back(s);return v;}
unsigned orbits(const set<P>&g){unsigned seen=0,n=0;for(unsigned v=0;v<g.begin()->size();v++)if(!(seen>>v&1)){n++;for(auto p:g)seen|=1u<<p[v];}return n;}
void hist(ostream&o,const map<unsigned,uint64_t>&h){o<<'[';bool first=true;for(auto x:h){if(!first)o<<',';first=false;o<<'['<<x.first<<','<<x.second<<']';}o<<']';}
int main(int argc,char**argv){try{req(argc==6,"usage: independent source-order source-atlas output-parent-atlas output-states output-report");unsigned m=stoi(argv[1]),n=m+1,k=n+1;req(m==5||m==7||m==9,"bounded source order");auto source=read_atlas(argv[2],m),atlas=read_atlas(argv[3],n);map<uint64_t,unsigned>lookup;uint64_t mass=0;map<unsigned,uint64_t>parenthist;for(unsigned i=0;i<atlas.size();i++){auto &o=atlas[i];req(ar(o.r),"parent almost regular");req(o.g==autos(o.r),"complete parent permutation action equality");req(lookup.emplace(canonical(o.r),i).second,"pairwise nonisomorphic parents");req(fac(n)%o.g.size()==0,"parent orbit divisor");mass+=fac(n)/o.g.size();++parenthist[o.g.size()];}
 vector<uint64_t>seen(atlas.size());uint64_t source_mass=0,raw=0,eligible=0;for(auto &o:source){bool possible=true;for(auto row:o.r)if(pc(row)<n/2-2||pc(row)>n/2)possible=false;if(!possible)continue;++eligible;for(unsigned mask=0;mask<(1u<<m);mask++){auto x=extend(o.r,mask);if(!ar(x))continue;++raw;source_mass+=fac(m)/o.g.size();auto it=lookup.find(canonical(x));req(it!=lookup.end(),"every eligible source extension found independently");++seen[it->second];}}for(auto z:seen)req(z>0,"every output parent generated");req(source_mass==mass,"independent generated and canonical masses equal");
 vector<map<unsigned,unsigned>>D(atlas.size());vector<unsigned>conv(atlas.size());uint64_t trace=0;for(unsigned i=0;i<atlas.size();i++){auto &r=atlas[i].r;unsigned mask=0;for(unsigned v=0;v<n;v++)if(pc(r[v])==n/2-1)mask|=1u<<v;auto child=extend(r,mask);for(auto row:child)req(pc(row)==n/2,"unique regular extension");for(unsigned v=0;v<k;v++){auto it=lookup.find(canonical(del(child,v)));req(it!=lookup.end(),"independent reroot destination exists");++D[i][it->second];}req(D[i].count(i),"self reroot");trace+=D[i].at(i);G rev=r;for(unsigned v=0;v<n;v++)rev[v]^=((1u<<n)-1)^(1u<<v);auto it=lookup.find(canonical(rev));req(it!=lookup.end(),"converse destination exists");conv[i]=it->second;}
 ifstream st(argv[4]);string line;getline(st,line);req(line=="state\tcomponent\tparent_aut_order\tpointed_source_states\tconverse_state\treroot_destinations","state header");vector<unsigned>component(atlas.size());unsigned lines=0;while(getline(st,line)){auto f=split(line,'\t');req(f.size()==6,"state field count");unsigned i=stoul(f[0]);req(i==lines&&i<atlas.size(),"ordered state rows");component[i]=stoul(f[1]);req(stoul(f[2])==atlas[i].g.size(),"state parent aut count");req(stoul(f[3])==orbits(atlas[i].g),"pointed states equal independently computed parent orbits");req(stoul(f[4])==conv[i],"every converse matches");map<unsigned,unsigned>given;for(auto item:split(f[5],',')){auto e=split(item,':');req(e.size()==2,"reroot pair");req(given.emplace(stoul(e[0]),stoul(e[1])).second,"distinct reroot destinations");}req(given==D[i],"every reroot destination and multiplicity matches");++lines;}req(lines==atlas.size(),"state table complete");
 map<unsigned,uint64_t>childhist,errhist;set<unsigned>done;uint64_t childmass=0,error=0,selfparents=0,selfchildren=0;unsigned components=0;for(unsigned i=0;i<atlas.size();i++){req(conv[conv[i]]==i,"converse involution");selfparents+=conv[i]==i;if(done.count(i))continue;unsigned mask=0;for(unsigned v=0;v<n;v++)if(pc(atlas[i].r[v])==n/2-1)mask|=1u<<v;auto child=extend(atlas[i].r,mask);auto aut=autos(child);req(orbits(aut)==D[i].size(),"full child action orbit count");unsigned sum=0;for(auto d:D[i]){unsigned j=d.first;req(done.insert(j).second,"disjoint components");req(component[j]==components,"component numbering agrees");req(D[j]==D[i],"all component rows identical");req(aut.size()==D[j].at(j)*atlas[j].g.size(),"full group agrees with every root stabilizer");sum+=d.second;}req(sum==k,"component root total");req(fac(k)%aut.size()==0,"child orbit divisor");childmass+=fac(k)/aut.size();unsigned e=k*(D[i].size()-1);error+=e;++errhist[e];++childhist[aut.size()];selfchildren+=D[i].count(conv[i]);++components;}
 req(trace==k*components,"trace class count");req(error==k*(atlas.size()-components),"regular error identity");req(childmass==mass,"regular labeled mass");ofstream out(argv[5]);out<<"{\n\"status\":\"PASS\",\n\"source_order\":"<<m<<",\n\"parent_classes\":"<<atlas.size()<<",\n\"eligible_source_parents\":"<<eligible<<",\n\"eligible_masks\":"<<raw<<",\n\"parent_labelled_mass\":"<<mass<<",\n\"regular_trace\":"<<trace<<",\n\"regular_classes\":"<<components<<",\n\"regular_error\":"<<error<<",\n\"self_converse_parents\":"<<selfparents<<",\n\"self_converse_regular\":"<<selfchildren<<",\n\"parent_aut_histogram\":";hist(out,parenthist);out<<",\n\"regular_aut_histogram\":";hist(out,childhist);out<<",\n\"error_histogram\":";hist(out,errhist);out<<",\n\"canonical_calls\":"<<can_calls<<",\n\"unrestricted_within_cell_labelings\":"<<can_leaves<<",\n\"automorphism_search_nodes\":"<<iso_nodes<<",\n\"checks\":"<<checks<<",\n\"target_canonicalizations\":0\n}\n";req(bool(out),"report written");cout<<"PASS parent="<<atlas.size()<<" regular="<<components<<" trace="<<trace<<" error="<<error<<" mass="<<mass<<"\n";
 }catch(exception&e){cerr<<e.what()<<'\n';return 1;}}
